#!/usr/bin/env node
// Synthetic Atlas 0.1 fixture generator for the S4-prep performance slice.
//
// IMPORTANT: these fixtures are SYNTHETIC (deterministically generated by this
// script from the small Demo snapshot template). They are NOT a real repository,
// not real Linux/Kbuild analysis, and must never be presented as Atlas facts.
// They only exercise the read-model/rendering at the 500-node and 2,000-node
// scales required by docs/ai-summary-perf-contract.md §2.
//
// Usage:
//   node tools/perf/make-synthetic-graph.mjs [--template <snapshot dir>] [--out <dir>]
//
// Outputs <out>/synthetic-500-800/{graph.json,analysis_manifest.json} and
// <out>/synthetic-2000-10k/... plus README.md.
import {createHash} from 'node:crypto';
import {cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync} from 'node:fs';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const TEMPLATE = join(REPO_ROOT, 'evidence', 'code-view-slice', 'inbox', 'snapshot-bus');
const OUT = join(REPO_ROOT, 'scratch', 'perf', 'fixtures');
const args = process.argv.slice(2);
const arg = (name, fallback) => { const index = args.indexOf(name); return index >= 0 && args[index + 1] !== undefined ? args[index + 1] : fallback; };
const templateDir = arg('--template', TEMPLATE);
const outDir = arg('--out', OUT);
const repoRoot = arg('--repo-root', join(REPO_ROOT, 'scratch', 'perf', 'repo'));

const hash = (value) => createHash('sha256').update(value).digest('hex');
const readJson = (path) => JSON.parse(readFileSync(path, 'utf8'));

function envelope(kind, payload) {
  const body = JSON.stringify({schema_version: '0.1', record_id: hash(JSON.stringify(payload)), record_kind: kind, payload, provenance: {
    configuration_id: null, evidence_ids: [], input_hash: 'synthetic', producer_kind: 'python', producer_version: '0.8.0-synthetic', task_id: 'synthetic-perf-fixture',
  }}, null, 2);
  return body;
}

function makeFixture(name, spec) {
  const graph = readJson(join(templateDir, 'graph.json'));
  const manifest = readJson(join(templateDir, 'analysis_manifest.json'));
  const payload = graph.payload;
  const templateFunction = payload.functions[0];
  const templateObject = payload.objects[0];
  const templateType = payload.types[0];
  const templateCallsite = payload.callsites[0];
  const templateEvidence = payload.evidence[0];
  const templateFlow = payload.flow_edges[0];
  const templateStateEvent = payload.state_events[0];

  const functions = [];
  const objects = [];
  const types = [];
  const evidence = [];
  const evidenceId = (index) => `e_syn${String(index).padStart(18, '0').slice(-18)}`;
  for (let index = 0; index < spec.functions; index += 1) {
    const source = templateFunction;
    // root-ref-qualified paths: engine source read resolves allowed read roots
    // as <root_ref>/<path>; the synthetic repo lives under scratch/perf/repo.
    const file = index % 7 === 0 ? 'perf-root/synthetic/platform.c' : 'perf-root/synthetic/bus.c';
    functions.push({
      ...source,
      id: `f_syn${String(index).padStart(20, '0')}`,
      base_id: `s_syn${String(index).padStart(20, '0')}`,
      display_name: `synthetic_fn_${index}()`,
      name: `synthetic_fn_${index}`,
      qualified_name: `synthetic_fn_${index}`,
      evidence_ids: [evidenceId(index % 64)],
      file: {file, line: 1 + (index % 200)},
      definition: {file, line: 1 + (index % 200)},
      tu_id: `tu_syn${String(index % 64).padStart(4, '0')}`,
    });
  }
  for (let index = 0; index < spec.objects; index += 1) {
    objects.push({
      ...templateObject,
      id: `s_synobj${String(index).padStart(16, '0')}`,
      name: `synthetic_obj_${index}`,
      evidence_ids: [evidenceId(index % 64)],
      tu_ids: [`tu_syn${String(index % 64).padStart(4, '0')}`],
    });
  }
  for (let index = 0; index < 4; index += 1) {
    types.push({...templateType, id: `s_syntype${index}`, base_id: `s_syntype${index}_base`, evidence_ids: [evidenceId(index)]});
  }
  for (let index = 0; index < 64; index += 1) {
    evidence.push({
      ...templateEvidence,
      id: evidenceId(index),
      file: index % 2 === 0 ? 'perf-root/synthetic/bus.c' : 'perf-root/synthetic/platform.c',
      line: 1 + index,
      start: index * 10,
      end: index * 10 + 8,
      text: `/* synthetic evidence ${index} */`,
    });
  }
  const callsites = [];
  const callTargets = [];
  for (let index = 0; index < spec.calls; index += 1) {
    const sourceIndex = index % spec.functions;
    const targetIndex = (index * 7 + 1) % spec.functions;
    const callsiteId = `c_syn${String(index).padStart(18, '0')}`;
    callsites.push({
      ...templateCallsite,
      id: callsiteId,
      owner: functions[sourceIndex].id,
      callee: functions[targetIndex].name,
      expression: `${functions[targetIndex].name}()`,
      evidence_ids: [evidenceId(index % 64)],
      file: functions[sourceIndex].file.file,
      line: 1 + (index % 200),
    });
    callTargets.push({
      ...templateFlow,
      id: `edge_syn${String(index).padStart(16, '0')}`,
      kind: 'call_target',
      callsite: callsiteId,
      source: functions[sourceIndex].id,
      target: functions[targetIndex].id,
      certainty: index % 3 === 0 ? 'may' : 'exact',
      evidence_ids: [evidenceId(index % 64)],
      origin: 'deterministic_analysis',
    });
  }
  const flowEdges = [];
  for (let index = 0; index < spec.flowEdges; index += 1) {
    const objectIndex = index % spec.objects;
    flowEdges.push({
      ...templateFlow,
      id: `flow_syn${String(index).padStart(16, '0')}`,
      kind: 'flows_to',
      owner: functions[index % spec.functions].id,
      target: objects[objectIndex].id,
      sources: [functions[(index * 5 + 3) % spec.functions].id],
      relation: 'reads_or_writes',
      evidence_ids: [evidenceId(index % 64)],
    });
  }
  const stateEvents = [];
  for (let index = 0; index < spec.events; index += 1) {
    stateEvents.push({
      ...templateStateEvent,
      id: `state_syn${String(index).padStart(16, '0')}`,
      kind: index % 2 === 0 ? 'write_or_initialize' : 'read',
      object_id: objects[index % spec.objects].id,
      owner: functions[index % spec.functions].id,
      evidence_ids: [evidenceId(index % 64)],
    });
  }
  const functionIds = new Set(functions.map((row) => row.id));
  const objectIds = new Set(objects.map((row) => row.id));
  const flowEdgesValid = flowEdges.filter((edge) => functionIds.has(edge.sources[0]) && objectIds.has(edge.target));
  const syntheticPayload = {
    ...payload,
    functions,
    objects,
    types,
    evidence,
    callsites,
    call_targets: callTargets,
    flow_edges: flowEdgesValid,
    state_events: stateEvents,
    field_accesses: (payload.field_accesses ?? []).slice(0, Math.min(200, spec.functions)).map((row, index) => ({
      ...row, id: `field_syn${index}`, owner: functions[index % spec.functions].id,
      field_id: objects[index % spec.objects].id, field_name: 'syn_field', object_ids: [objects[index % spec.objects].id], evidence_ids: [evidenceId(index % 64)],
    })),
    shared_accesses: [
      ...(payload.shared_accesses ?? []).slice(0, Math.min(200, spec.functions)).map((row, index) => ({
        ...row, id: `access_syn${index}`, owner: functions[index % spec.functions].id,
        object_id: objects[index % spec.objects].id, evidence_ids: [evidenceId(index % 64)],
      })),
      // Entry-neighborhood accesses: the coupling view scopes to the entry, so
      // give synthetic_fn_0 a writer/reader pair on a synthetic object.
      {id: 'access_synentry0', kind: 'shared_access', access: 'write', certainty: 'may', origin: 'synthetic',
       owner: functions[0].id, object_id: objects[0].id, evidence_ids: [evidenceId(0)],
       limitations: ['synthetic_perf_fixture'], field_path: ['syn_field'], tu_ids: []},
      {id: 'access_synentry1', kind: 'shared_access', access: 'read', certainty: 'may', origin: 'synthetic',
       owner: functions[1].id, object_id: objects[0].id, evidence_ids: [evidenceId(1)],
       limitations: ['synthetic_perf_fixture'], field_path: ['syn_field'], tu_ids: []},
    ],
    concurrency_findings: [],
    boundaries: (payload.boundaries ?? []).slice(0, Math.min(20, spec.functions)).map((row, index) => ({
      ...row, callee: `synthetic_external_${index}`, callsite: callsites[index].id, owner: functions[index].id, evidence_ids: [evidenceId(index % 64)],
    })),
    scope: {...payload.scope, target: functions[0].id},
    coverage: {...payload.coverage, truncated: true, complete_call_chain: false, failed: [], pending_units: []},
    issues: (payload.issues ?? []).slice(0, 10).map((row, index) => ({...row, id: `i_syn${index}`, affected_scope: functions[index].id, evidence_ids: [evidenceId(index % 64)]})),
  };
  const graphRaw = envelope('graph', syntheticPayload);
  const graphHash = hash(Buffer.from(graphRaw, 'utf8'));
  const syntheticManifestPayload = {
    ...manifest.payload,
    snapshot_id: name,
    analysis_id: name,
    tool_version: '0.8.0-synthetic',
    graph_hash: graphHash,
    coverage: {...manifest.payload.coverage, truncated: true, complete_call_chain: false, failed: [], pending_units: [],
      parsed: spec.functions, processed_units: spec.functions, total_available_units: spec.functions, requested_scope_complete: true},
    parameters: {...manifest.payload.parameters, synthetic: true},
    workspace_roots: [repoRoot],
    workspace_revisions: {[repoRoot]: 'synthetic'},
    input_files: {[join(repoRoot, 'synthetic', 'bus.c')]: null, [join(repoRoot, 'synthetic', 'platform.c')]: null},
    assumptions: ['synthetic_perf_fixture_not_real_repository', 'generated_by_tools_perf_make_synthetic_graph'],
  };
  const manifestRaw = envelope('analysis_manifest', syntheticManifestPayload);
  const dir = join(outDir, name);
  rmSync(dir, {recursive: true, force: true});
  mkdirSync(dir, {recursive: true});
  writeFileSync(join(dir, 'graph.json'), graphRaw, 'utf8');
  writeFileSync(join(dir, 'analysis_manifest.json'), manifestRaw, 'utf8');
  return {
    name, dir, functions: functions.length, objects: objects.length,
    calls: callTargets.length, flow_edges: flowEdgesValid.length, state_events: stateEvents.length,
    nodes: functions.length + objects.length, edges: callTargets.length + flowEdgesValid.length,
    graph_sha256: graphHash,
  };
}

if (!existsSync(join(templateDir, 'graph.json'))) {
  console.error(`synthetic fixture template missing: ${templateDir}`);
  process.exit(1);
}
mkdirSync(outDir, {recursive: true});
const fixtures = [
  makeFixture('synthetic-500-800', {functions: 400, objects: 100, calls: 500, flowEdges: 300, events: 1500}),
  makeFixture('synthetic-2000-10k', {functions: 1600, objects: 400, calls: 2000, flowEdges: 1200, events: 10000}),
];
const readme = `# Synthetic perf fixtures (NOT a real repository)

Generated by \`tools/perf/make-synthetic-graph.mjs\` from the small Demo Atlas
template for **performance measurement only** (docs/ai-summary-perf-contract.md §2).
They are deterministic, legal Atlas 0.1 envelope pairs (graph.json + analysis_manifest.json,
manifest.graph_hash = sha256(graph.json bytes)) but they are **not** real
Linux/Kbuild analysis and must never be cited as Atlas facts or product evidence.

| fixture | nodes | edges | state events | graph sha256 |
|---|---|---|---|---|
| synthetic-500-800 | ${fixtures[0].nodes} | ${fixtures[0].edges} | ${fixtures[0].state_events} | ${fixtures[0].graph_sha256} |
| synthetic-2000-10k | ${fixtures[1].nodes} | ${fixtures[1].edges} | ${fixtures[1].state_events} | ${fixtures[1].graph_sha256} |

Regenerate: \`node tools/perf/make-synthetic-graph.mjs\`.
`;
writeFileSync(join(outDir, 'README.md'), readme, 'utf8');
process.stdout.write(`${JSON.stringify({ok: true, out: outDir, fixtures}, null, 2)}\n`);
